def iter_bbox(di,do,bg,iters=5):
    g=np.array(di); o=np.array(do); R,C=g.shape
    mask=(g!=bg)
    for it in range(iters):
        lab,n=ndimage.label(mask)
        boxes=[]
        for i in range(1,n+1):
            rs,cs=np.where(lab==i)
            boxes.append((rs.min(),rs.max(),cs.min(),cs.max()))
        newbg=np.zeros_like(mask)
        for r in range(R):
            for c in range(C):
                if g[r,c]==bg and any(a<=r<=b and d<=c<=e for a,b,d,e in boxes):
                    newbg[r,c]=True
        if (newbg==mask).all(): break
        mask=mask|newbg
    kept=set()
    for r in range(R):
        for c in range(C):
            if g[r,c]==bg and mask[r,c]: kept.add((r,c))
    truekept={(int(r),int(c)) for r,c in np.argwhere((g==bg)&(o==bg))}
    return kept==truekept, sorted(truekept-kept), sorted(kept-truekept), it
