            # gap fill: bg with fg directly above and below (any objects), or left&right
            up = r>0 and g[r-1,c]!=bg; dn=r<R-1 and g[r+1,c]!=bg
            lf = c>0 and g[r,c-1]!=bg; rt=c<C-1 and g[r,c+1]!=bg
